// ═══ RETHROW: throw e — pass original unchanged ═══
public void processPayment(String paymentId) throws PaymentException {
    try {
        gateway.charge(paymentId);
    } catch (PaymentException e) {
        log.warn("Payment failed: {}", paymentId);
        throw e;  // RETHROW: same type, message, stack trace
        // Caller sees: PaymentException exactly as gateway threw it
        // Use when: this layer has nothing to add, just log + forward
    }
}

// ═══ WRAP: throw new ServiceException("msg", e) — translate ═══
public TradeResult settle(String tradeId) {
    try {
        BigDecimal amount = repo.findAmount(tradeId);
        gateway.transfer(amount);
    } catch (SQLException e) {
        // WRAP: translate technical → business domain
        throw new SettlementException("Settlement failed for " + tradeId, e);
        // ✅ cause preserved! Stack trace: SettlementException → Caused by: SQLException
        // Caller sees business exception, can still inspect root cause
    }
}

// ❌ WRONG: wrap WITHOUT cause — root cause LOST!
catch (SQLException e) {
    throw new SettlementException("Settlement failed for " + tradeId);
    // NO cause! "Caused by:" section GONE! Was it deadlock? Constraint? Timeout? UNKNOWN!
}

// ═══ JAVA 7 PRECISE RETHROW ═══
// Before Java 7:
public void process() throws Exception {  // forced to declare broad Exception!
    try {
        readFile();   // throws IOException
        queryDb();    // throws SQLException
    } catch (Exception e) {
        log.error("Failed", e);
        throw e;      // compiler sees: e is Exception → must declare throws Exception
    }
}

// Java 7+: precise rethrow!
public void process() throws IOException, SQLException {  // SPECIFIC types!
    try {
        readFile();   // throws IOException
        queryDb();    // throws SQLException
    } catch (Exception e) {
        log.error("Failed", e);
        throw e;      // compiler KNOWS: only IOException/SQLException can reach here!
        // e is "effectively final" (not reassigned) → compiler narrows the type
    }
}

// ❌ Precise rethrow BREAKS if you reassign e:
catch (Exception e) {
    e = new RuntimeException("replaced");  // reassigned!
    throw e;  // compiler: e could be anything now → must declare throws Exception
}
