package com.bank.rethrow;

import org.junit.jupiter.api.Test;
import java.io.IOException;
import java.sql.SQLException;
import static org.assertj.core.api.Assertions.*;

class RethrowVsWrapTest {

    // ═══ RETHROW: same exception forwarded ═══
    @Test
    void rethrow_preservesOriginal() {
        SQLException original = new SQLException("Deadlock detected");

        assertThatThrownBy(() -> {
            try {
                throw original;
            } catch (SQLException e) {
                // log, then rethrow
                throw e;  // SAME object!
            }
        })
        .isSameAs(original)  // exact same instance!
        .isInstanceOf(SQLException.class)
        .hasMessage("Deadlock detected");
    }

    // ═══ WRAP: translated with cause preserved ═══
    @Test
    void wrap_translateWithCause() {
        assertThatThrownBy(() -> {
            try {
                throw new SQLException("Connection timeout");
            } catch (SQLException e) {
                throw new RuntimeException("Settlement failed for TRD-001", e);
                // WRAP: new exception wraps original as cause
            }
        })
        .isInstanceOf(RuntimeException.class)
        .hasMessage("Settlement failed for TRD-001")
        .hasCauseInstanceOf(SQLException.class)  // cause preserved!
        .hasRootCauseMessage("Connection timeout");
    }

    // ═══ WRAP WITHOUT CAUSE — anti-pattern ═══
    @Test
    void wrapWithoutCause_rootCauseLost() {
        assertThatThrownBy(() -> {
            try {
                throw new SQLException("Unique constraint violated");
            } catch (SQLException e) {
                throw new RuntimeException("Settlement failed");  // NO cause!
            }
        })
        .isInstanceOf(RuntimeException.class)
        .hasNoCause();  // ROOT CAUSE LOST! Was it deadlock? Timeout? Constraint? UNKNOWN!
    }

    // ═══ PRECISE RETHROW (Java 7+) ═══
    @Test
    void preciseRethrow_narrowsType() throws IOException, SQLException {
        // This method declares throws IOException, SQLException (NOT Exception)
        // even though the catch block catches Exception.
        // Java 7 compiler analyzes: only IOException/SQLException thrown in try body.
        String input = "valid";
        try {
            if (input.isEmpty()) throw new IOException("File error");
            if (input.isBlank()) throw new SQLException("DB error");
            // Only IOException and SQLException possible in try body
        } catch (Exception e) {
            // e can only be IOException or SQLException → precise rethrow!
            // throw e;  → compiler allows: throws IOException, SQLException
            // (not demonstrated here since input is valid → no exception)
        }
    }

    // ═══ WHEN TO RETHROW vs WRAP ═══
    @Test
    void decisionGuide() {
        // RETHROW (throw e):
        //   Same abstraction level: service → service
        //   Nothing to add: just log + forward
        //   Caller already understands the exception type

        // WRAP (throw new X("msg", e)):
        //   Cross abstraction boundary: repository → service → controller
        //   Translate technical → business: SQLException → SettlementException
        //   Add context: "Settlement failed for TRD-001"
        //   ALWAYS pass cause: new X("msg", e) — not new X("msg")!
        assertThat(true).isTrue();
    }
}
